import { Pool } from "pg";

export interface Ticket {
  id: string;
  tenantId: string;
  subject: string;
  status: "open" | "pending" | "solved";
  assigneeId: string | null;
}

export class TicketRepository {
  constructor(private readonly pool: Pool) {}

  async findById(tenantId: string, ticketId: string): Promise<Ticket | null> {
    try {
      const { rows } = await this.pool.query(
        `SELECT id, tenant_id, subject, status, assignee_id
           FROM tickets WHERE tenant_id = $1 AND id = $2`,
        [tenantId, ticketId],
      );
      if (rows.length === 0) return null;
      const r = rows[0];
      return {
        id: r.id,
        tenantId: r.tenant_id,
        subject: r.subject,
        status: r.status,
        assigneeId: r.assignee_id,
      };
    } catch (err) {
      console.error("ticket lookup failed", { tenantId, ticketId, err });
      return null;
    }
  }

  async assign(tenantId: string, ticketId: string, agentId: string): Promise<void> {
    const res = await this.pool.query(
      `UPDATE tickets SET assignee_id = $3, updated_at = now()
        WHERE tenant_id = $1 AND id = $2`,
      [tenantId, ticketId, agentId],
    );
    if (res.rowCount === 0) {
      throw new Error(`ticket ${ticketId} vanished during assignment`);
    }
  }
}

import { Ticket, TicketRepository } from "./ticketRepository";

export class NotFoundError extends Error {
  readonly status = 404;
}
export class ConflictError extends Error {
  readonly status = 409;
}

export interface AgentDirectory {
  isActiveAgent(tenantId: string, agentId: string): Promise<boolean>;
}

export class AssignmentService {
  constructor(
    private readonly tickets: TicketRepository,
    private readonly agents: AgentDirectory,
  ) {}

  async assign(tenantId: string, ticketId: string, agentId: string): Promise<Ticket> {
    const ticket = await this.tickets.findById(tenantId, ticketId);
    if (!ticket) {
      throw new NotFoundError(`ticket ${ticketId} not found`);
    }
    if (ticket.status === "solved") {
      throw new ConflictError(`ticket ${ticketId} is already solved`);
    }
    if (!(await this.agents.isActiveAgent(tenantId, agentId))) {
      throw new ConflictError(`agent ${agentId} cannot take tickets`);
    }
    await this.tickets.assign(tenantId, ticketId, agentId);
    return { ...ticket, assigneeId: agentId };
  }
}

import express, { NextFunction, Request, Response } from "express";
import { AssignmentService } from "./assignmentService";

export function assignmentRouter(service: AssignmentService) {
  const router = express.Router();

  router.post(
    "/tenants/:tenantId/tickets/:ticketId/assignee",
    async (req: Request, res: Response, next: NextFunction) => {
      const agentId = typeof req.body?.agentId === "string" ? req.body.agentId : "";
      if (!agentId) {
        res.status(400).json({ error: "agentId is required" });
        return;
      }
      try {
        const ticket = await service.assign(req.params.tenantId, req.params.ticketId, agentId);
        res.status(200).json(ticket);
      } catch (err) {
        next(err);
      }
    },
  );

  router.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    const status = typeof (err as { status?: unknown }).status === "number"
      ? (err as { status: number }).status
      : 500;
    const message = status < 500 && err instanceof Error ? err.message : "internal error";
    res.status(status).json({ error: message });
  });

  return router;
}

